function range(start, end, step = 1) {
  // Guard against a zero step, which would loop forever
  if (step === 0) throw new Error('step must not be 0');
  // Collect values from start up to (but not including) end
  const result = [];
  for (let i = start; step > 0 ? i < end : i > end; i += step) {
    result.push(i);
  }
  return result; // Return the collected sequence
}

